// Synthetic-only conflict fixture: native Add on an existing pair, no raw KV writes.
#include "remove_support.hpp"
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("args");auto root=checkedPath(argv[1]),job=checkedPath(argv[2]);checkedInputs(root,job);if((root.filename().string().find("wetype-lab-batch-success-")!=0&&root.filename().string().find("wetype-lab-sync-selftest-")!=0)||!fs::is_regular_file(root/"SYNTHETIC_REMOVE_TESTS_ONLY"))throw std::runtime_error("synthetic permit");isolate(root,job);loadSecret(job);std::ifstream f(job/"request.tsv");std::string line;if(!std::getline(f,line)||line.size()>1024||f.peek()!=EOF)throw std::runtime_error("one row");auto tab=line.find('\t');if(tab==std::string::npos||line.find('\t',tab+1)!=std::string::npos)throw std::runtime_error("row");auto py=line.substr(0,tab),word=line.substr(tab+1);if(!validPinyin(py)||!validUtf8Word(word))throw std::runtime_error("input");RemoveEngine e(root,job,1);auto user=learningDict(e.h);using Pair=uint64_t(*)(void*,std::string_view,std::string_view);using Add=std::function<void()>(*)(void*,std::string_view,std::string_view,const AddOption&);uint64_t before=entry<Pair>(e.slide,kLookUpPair)(user.get(),py,word);if(!((before>>32)&1))throw std::runtime_error("fixture must exist");AddOption opt;auto wait=entry<Add>(e.slide,kAdd)(user.get(),py,word,opt);if(wait)wait();uint64_t after=entry<Pair>(e.slide,kLookUpPair)(user.get(),py,word);if(!((after>>32)&1)||(uint32_t)after!=(uint32_t)before+1)throw std::runtime_error("native learning did not increment");printf("NATIVE_LEARN_COMPLETE count_before=%u count_after=%u\n",(uint32_t)before,(uint32_t)after);return 0;}catch(...){fputs("synthetic native learning rejected\n",stderr);_exit(43);}}
